infra.infra/prod/main.tf:
terraform {
  backend "s3" {}
}
resource "aws_iam_role" "r" {
  name               = "r"
  assume_role_policy = "{}"
}
resource "aws_iam_role_policy" "p" {
  role   = aws_iam_role.r.name
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "secretsmanager:GetSecretValue", Resource = "arn:aws:secretsmanager:*:*:secret:prod/db-*" }] })
}

terraform {
  backend "s3" {}
}
variable "audit_account_id" {}
resource "aws_iam_role" "r" {
  name               = "r"
  assume_role_policy = "{}"
}
resource "aws_kms_key" "k" {
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = { AWS = aws_iam_role.r.arn }, Action = "kms:Encrypt", Resource = "*" }, { Effect = "Allow", Principal = { AWS = "arn:aws:iam::${var.audit_account_id}:root" }, Action = "kms:*", Resource = "*" }] })
}
resource "aws_sqs_queue" "jobs" {
  name              = "jobs"
  kms_master_key_id = aws_kms_key.k.arn
}
resource "aws_iam_role_policy" "p" {
  role   = aws_iam_role.r.name
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = ["sqs:SendMessage", "kms:GenerateDataKey", "kms:Decrypt"], Resource = "*" }] })
}
resource "aws_lambda_function" "f" {
  function_name = "f"
  role          = aws_iam_role.r.arn
  environment {
    variables = { JOBS_QUEUE_URL = aws_sqs_queue.jobs.url }
  }
}

base.r/main.tf:
terraform {
  backend "s3" {}
}
data "aws_ssm_parameter" "a" {
  name = "a"
}
resource "aws_dynamodb_table" "t" {
  name     = "orders"
  hash_key = "id"
  local_secondary_index {
    name            = data.aws_ssm_parameter.a.value
    range_key       = "sk"
    projection_type = "ALL"
  }
}

